Item", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同比和环比搞混"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "百分数和百分点搞混"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "基期和现期搞反"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "统计术语是资料分析的基础。同比看年份，环比看相邻期，百分数是比率，百分点是差值。"}]}]}]}$$ AS jsonb), NULL, '资料分析-统计术语的核心知识点和解题方法。', category_node.id, CAST('["资料分析", "统计术语"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_statistical_terms", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
